#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long value;
    int factor;
} Node;

int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

void sift_down(Node heap[], int size, int i) {
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = left + 1;

        if (left < size && heap[left].value < heap[smallest].value)
            smallest = left;
        if (right < size && heap[right].value < heap[smallest].value)
            smallest = right;

        if (smallest == i)
            break;

        Node temp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = temp;
        i = smallest;
    }
}

void sift_up(Node heap[], int i) {
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent].value <= heap[i].value)
            break;

        Node temp = heap[i];
        heap[i] = heap[parent];
        heap[parent] = temp;
        i = parent;
    }
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2)
        return 0;

    int *times = malloc((size_t)N * sizeof(int));
    Node *heap = malloc((size_t)M * sizeof(Node));

    for (int i = 0; i < N; i++)
        scanf("%d", &times[i]);

    for (int i = 0; i < M; i++) {
        scanf("%d", &heap[i].factor);
        heap[i].value = 0;
    }

    qsort(times, N, sizeof(int), compare_ints);

    for (int i = M / 2 - 1; i >= 0; i--)
        sift_down(heap, M, i);

    long long answer = 0;

    for (int i = 0; i < N; i++) {
        long long coefficient = heap[0].value;
        answer += (long long)times[N - 1 - i] * coefficient;

        heap[0].value += heap[0].factor;
        sift_down(heap, M, 0);
    }

    printf("%lld\n", answer);

    free(times);
    free(heap);
    return 0;
}
